// 与服务端共用的同一份生命周期规则：按钮显示什么、接口放行什么，都从这一个模块读，杜绝两处各写一套
import { availableActions, checkTransition, splitBalance, taskGranularity, deriveProgress, STATUS_META, FLOW, SPLIT, TERMINATED } from '/lifecycle.js';
const state={view:'dashboard',db:null,me:null,timeline:null,files:null,history:[],splitDraft:[],selectedRequirementId:null,filter:{status:'全部',projectId:'全部',q:''},selectedProjectId:'全部'};
const ROLE_ADMIN='项目管理';
const ROLES=[[ROLE_ADMIN,'维护账号与模型配置，看全局项目、甘特图、健康度和风险'],['产品','录入需求、排序、评审、创建项目与排期'],['开发','查看并更新自己的任务进度、提交风险'],['测试','维护测试用例任务、验证交付质量并更新状态']];
const $=s=>document.querySelector(s); const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const api=async(path,options={})=>{const r=await fetch(path,{credentials:'same-origin',headers:{'content-type':'application/json'},...options});const d=await r.json();if(!r.ok){const e=Error(d.error||'请求失败');e.status=r.status;e.gates=d.gates||[];e.details=d.details||[];e.code=d.code;throw e;}return d};
const toast=msg=>{const el=$('#toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2400)};
const project=id=>state.db.projects.find(x=>x.id===id);const user=id=>state.db.users.find(x=>x.id===id);
const todayLabel=()=>{const d=new Date();return `${d.getFullYear()} 年 ${d.getMonth()+1} 月 ${d.getDate()} 日`};
const pill=(v,kind='status')=>`<span class="pill ${kind==='priority'?v.toLowerCase():'status-'+esc(v)}">${esc(v)}</span>`;
function shell(){return `<div class="shell"><aside class="side"><div class="brand"><span class="logo">星</span><span>星河研发台</span><small>AI PRODUCT STUDIO</small></div><button class="quick" data-action="new-requirement">＋ <span>快速创建需求</span></button><div class="section">工作台</div><nav class="nav">${[['dashboard','▦','总览看板'],['requirements','☷','需求池'],['projects','▣','项目空间'],['tasks','✓','研发排期'],['timeline','▤','项目甘特图'],['users','♙','账号管理'],['settings','⚙','模型配置']].map(x=>`<button class="${state.view===x[0]?'active':''}" data-view="${x[0]}"><b>${x[1]}</b><span>${x[2]}</span></button>`).join('')}</nav><div class="sidefoot"><button class="side-logout" data-action="logout"><span class="side-logout-icon">⏻</span><span class="side-logout-text">退出登录</span></button></div></aside><main class="main"><header class="top"><div><div class="crumb">工作台 / ${title()}</div><h1>${title()}</h1></div><input id="global-search" placeholder="搜索需求、任务、项目" value="${esc(state.filter.q)}"><div class="top-user"><button class="user-menu-btn" data-action="toggle-user-menu" aria-haspopup="true" aria-expanded="false"><span class="avatar">${esc((state.me?.name||'').slice(0,1))}</span><span class="user-meta"><b>${esc(state.me?.name||'')}</b><small>${esc(state.me?.role||'')}</small></span><span class="caret">▾</span></button><div class="user-menu hidden" id="user-menu"><div class="user-menu-head"><b>${esc(state.me?.name||'')}</b><div class="muted">${esc(state.me?.title||state.me?.role||'')}</div></div><button class="user-menu-item" data-view="settings">模型配置</button><button class="user-menu-item danger" data-action="logout">退出登录</button></div></div></header><section class="content">${view()}</section></main></div>`}
function title(){if(state.view==='requirement')return '需求详情';return {dashboard:'项目总览',requirements:'需求池',projects:'项目空间',tasks:'研发排期',timeline:'项目甘特图',users:'账号管理',settings:'模型配置'}[state.view]||'工作台'}
function dashboard(){const db=state.db, done=db.tasks.filter(x=>x.status==='已完成').length, active=db.tasks.filter(x=>['开发中','测试中'].includes(x.status)).length, selected=db.requirements.filter(x=>['开发中','测试中'].includes(x.status)).length;return `<div class="row"><div><div class="muted">${todayLabel()}</div><div class="title">早上好，${esc(state.me?.name||'')} 👋</div></div><button class="btn primary" data-action="new-requirement">＋ 新建需求</button></div><div class="grid stats">${[['需求总数',db.requirements.length,'全部候选'],['需求进行中',selected,'开发或测试中'],['进行中任务',active,'开发或测试'],['项目数量',db.projects.length,'跨项目组合']].map(x=>`<div class="card stat"><div class="label">${x[0]}</div><div class="num">${x[1]}</div><div class="muted">${x[2]}</div></div>`).join('')}</div><div class="grid cols"><div class="card section-card"><div class="row"><div><b>项目进度</b><div class="muted">以项目为一级边界，统一查看交付健康度</div></div><button class="btn" data-view="timeline">看甘特图</button></div><ul class="list">${db.projects.map(p=>{const ts=db.tasks.filter(x=>x.projectId===p.id),pct=ts.length?Math.round(ts.filter(x=>x.status==='已完成').length/ts.length*100):0;return `<li><div style="flex:1"><b>${esc(p.name)}</b><div class="muted">${esc(p.description)}</div><div class="bar" style="margin-top:9px"><i style="width:${Math.max(pct,20)}%"></i></div></div><div>${pill(p.status)}<div class="muted" style="margin-top:8px;text-align:right">${pct||'进行中'}%</div></div></li>`}).join('')}</ul></div><div class="card section-card"><b>需要关注</b><ul class="list">${db.requirements.filter(x=>x.status!=='已完成').slice(0,4).map(r=>`<li><div><b>${esc(r.title)}</b><div class="muted">${esc(r.status)} · ${esc(project(r.projectId)?.name)}</div></div>${pill(r.priority,'priority')}</li>`).join('')}</ul></div></div>`}
function requirements(){
 const db=state.db;
 const visibleProjects=db.projects.filter(p=>state.filter.projectId==='全部'||p.id===state.filter.projectId);
 const selected=state.selectedProjectId==='全部'?'全部':(visibleProjects.some(p=>p.id===state.selectedProjectId)?state.selectedProjectId:(visibleProjects[0]?.id||'全部'));
 state.selectedProjectId=selected;
 const rows=db.requirements.filter(r=>
   (selected==='全部'||r.projectId===selected)&&
   (state.filter.status==='全部'||r.status===state.filter.status)&&
   (!state.filter.q||`${r.title}${r.description}${r.source}`.toLowerCase().includes(state.filter.q.toLowerCase()))
 );
 const allCount=db.requirements.filter(r=>state.filter.status==='全部'||r.status===state.filter.status).length;
 const projectItem=(p)=>{const rs=db.requirements.filter(r=>r.projectId===p.id), active=rs.filter(r=>!['已完成',TERMINATED].includes(r.status)).length;return `<button class="project-nav-item ${selected===p.id?'selected':''}" data-project-select="${p.id}"><span class="project-nav-icon">${esc(p.name.slice(0,1))}</span><span class="project-nav-copy"><b>${esc(p.name)}</b><small>${rs.length} 条需求 · ${active} 条待交付</small></span><span class="project-nav-count">${rs.length}</span></button>`};
 return `<div class="row requirements-head"><div><div class="eyebrow">REQUIREMENT BACKLOG</div><div class="title">需求池</div><div class="muted">先按项目聚合，再在项目内管理需求优先级与交付状态。未归属需求保留在统一收集箱，不会混入具体项目。</div></div><button class="btn primary" data-action="new-requirement">＋ 新建需求</button></div>
 <div class="card req-workspace"><aside class="req-projects"><div class="req-pane-head"><div><b>项目</b><span>${visibleProjects.length} 个项目</span></div><button class="icon-btn" title="查看全部" data-project-select="全部">⌂</button></div><div class="req-search"><input id="req-search" placeholder="搜索项目或需求" value="${esc(state.filter.q)}"></div><div class="project-nav-list"><button class="project-nav-item ${selected==='全部'?'selected':''}" data-project-select="全部"><span class="project-nav-icon all">⌘</span><span class="project-nav-copy"><b>全部项目</b><small>${allCount} 条需求 · 跨项目视图</small></span><span class="project-nav-count">${allCount}</span></button>${visibleProjects.map(projectItem).join('')}</div></aside><section class="req-list-pane"><div class="req-list-head"><div><div class="eyebrow">${selected==='全部'?'ALL PROJECTS':esc(project(selected)?.name||'PROJECT')}</div><h2>${selected==='全部'?'全部需求':esc(project(selected)?.name||'项目需求')}</h2><p>${selected==='全部'?'跨项目查看需求池，适合做全局优先级排序。':'该项目下的需求、优先级、负责人和系统状态。'}</p></div><div class="req-head-actions"><select id="status-filter"><option>全部</option><option>未确定</option><option>待评审</option><option>已确定</option><option>已排期</option><option>开发中</option><option>测试中</option><option>已完成</option></select><span class="result-count">${rows.length} 条</span></div></div><div class="req-table-wrap">${rows.length?`<table class="req-table"><thead><tr><th>需求</th><th>优先级</th><th>负责人</th><th>状态</th><th>工作量</th></tr></thead><tbody>${rows.map(r=>`<tr class="req-row" data-open-requirement="${esc(r.id)}" title="打开需求详情"><td><div class="req-title-cell"><span class="req-type-dot"></span><div><b>${esc(r.title)}</b><small>${esc(r.source||'需求池')} · ${esc(r.description||'暂无描述')}</small></div></div></td><td>${pill(r.priority,'priority')}</td><td>${esc(user(r.ownerId)?.name||'待分配')}</td><td>${pill(r.status)}</td><td>${r.estimatePoints||0} pts</td></tr>`).join('')}</tbody></table>`:`<div class="empty-state"><div class="empty-icon">⌁</div><b>这个项目还没有匹配的需求</b><span>可以切换筛选条件，或直接创建一条新需求。</span><button class="btn primary" data-action="new-requirement">创建需求</button></div>`}</div></section></div>`;
}
function projects(){return `<div class="row"><div><div class="title">项目空间</div><div class="muted">多个项目并行时，项目是需求、迭代、任务和里程碑的一级边界。</div></div><button class="btn primary" data-action="new-project">＋ 新建项目</button></div><div class="grid project-grid">${state.db.projects.map(p=>{const rs=state.db.requirements.filter(x=>x.projectId===p.id),ts=state.db.tasks.filter(x=>x.projectId===p.id);return `<div class="card project"><h3>${esc(p.name)}</h3><div class="muted">${esc(p.description)}</div><div style="margin:18px 0">${pill(p.status)}</div><div class="bar"><i style="width:${Math.max(20,Math.min(95,ts.length*18))}%"></i></div><div class="muted" style="display:flex;justify-content:space-between;margin-top:9px"><span>${rs.length} 个需求 · ${ts.length} 个任务</span><span>交付 ${p.targetDate}</span></div></div>`}).join('')}</div>`}
function tasks(){return `<div class="row"><div><div class="title">研发排期</div><div class="muted">任务状态是开发执行层，需求状态不是任务状态。</div></div><button class="btn primary" data-action="new-task">＋ 添加任务</button></div><div class="card"><div class="table-wrap"><table><thead><tr><th>任务</th><th>项目</th><th>负责人</th><th>状态</th><th>开始</th><th>截止</th></tr></thead><tbody>${state.db.tasks.map(t=>`<tr><td><b>${esc(t.title)}</b><div class="muted">${esc(t.estimateHours)}h · ${esc(t.requirementId)}</div></td><td>${esc(project(t.projectId)?.name)}</td><td>${esc(user(t.ownerId)?.name)}</td><td><select data-task-status="${t.id}">${['待开始','开发中','测试中','已完成'].map(s=>`<option ${s===t.status?'selected':''}>${s}</option>`).join('')}</select></td><td>${t.startDate}</td><td>${t.dueDate}</td></tr>`).join('')}</tbody></table></div></div>`}
const DAY=864e5, BAR_H=26, BAR_GAP=9, BAR_PAD=15;
const ganttDate=v=>{const d=new Date(v);return `${d.getMonth()+1}/${d.getDate()}`};
const ganttPct=(ms,start,span)=>Math.max(0,Math.min(100,(ms-start)/span*100));
const STATUS_CLASS={'待开始':'st-todo','开发中':'st-dev','测试中':'st-qa','已完成':'st-done'};
function ganttBar(b,tl){const s=new Date(b.startDate+'T00:00:00').getTime();let e=new Date(b.dueDate+'T00:00:00').getTime()+DAY-1;
if(e<s)e=s;const left=ganttPct(s,tl.range.startMs,tl.range.spanMs),width=Math.max(0.8,ganttPct(e,tl.range.startMs,tl.range.spanMs)-left);
const cls=[STATUS_CLASS[b.status]||'st-todo',b.late?'is-late':'',b.afterTarget?'is-overtarget':''].join(' ');
const tip=`${b.title} · ${b.ownerName} · ${b.startDate} → ${b.dueDate} · ${b.estimateHours||0}h${b.late?' · 已逾期':''}${b.afterTarget?' · 超出项目目标日期':''}`;
return `<div class="gbar ${cls}" style="left:${left}%;width:${width}%" title="${esc(tip)}"><span>${esc(b.title)}</span></div>`}
function timeline(){const tl=state.timeline;
 if(!tl)return `<div class="row"><div><div><div class="eyebrow">DELIVERY ROADMAP</div><div class="title">项目甘特图</div><div class="muted">项目管理视角：跨项目交付节点、进度偏差与资源占用。</div></div></div></div><div class="card section-card"><div class="muted">正在加载交付视图…</div></div>`;
 const days=Math.max(1,Math.round(tl.range.spanMs/DAY));
 const parts=tl.range.start.split('-').map(Number);
 const dayCells=Array.from({length:days},(_,i)=>{const d=new Date(Date.UTC(parts[0],parts[1]-1,parts[2])+i*DAY);return {i,label:d.getUTCDate(),month:d.getUTCMonth(),dow:d.getUTCDay(),weekend:d.getUTCDay()===0||d.getUTCDay()===6}});
 const monthGroups=[];dayCells.forEach(c=>{const g=monthGroups[monthGroups.length-1];if(g&&g.month===c.month)g.count++;else monthGroups.push({month:c.month,count:1,year:new Date(Date.UTC(parts[0],c.month,1)).getUTCFullYear()})});
 const todayPct=ganttPct(Date.parse(tl.range.today),tl.range.startMs,tl.range.spanMs);
 const todayIn=Date.parse(tl.range.today)>=tl.range.startMs&&Date.parse(tl.range.today)<=tl.range.endMs;
 const m=tl.metrics, healthCls=m.health==='风险'?'status-未确定':m.health==='关注'?'status-待评审':'status-已完成';
 const rowHeight=l=>Math.max(1,l.bars.length)*(BAR_H+BAR_GAP)+BAR_PAD*2;
 return `<div class="row"><div><div class="eyebrow">DELIVERY ROADMAP</div><div class="title">项目甘特图</div><div class="muted">项目管理视角：跨项目交付节点、进度偏差与资源占用。</div></div><div class="gantt-tools"><span class="gantt-pan-hint">按住鼠标左键拖动时间轴</span><button class="btn" data-action="gantt-fit">整体查看</button><button class="btn" data-action="gantt-zoom-out" aria-label="缩小时间轴">−</button><button class="btn" data-action="gantt-zoom-in" aria-label="放大时间轴">＋</button><button class="btn" data-action="print-timeline">导出视图</button>${pill(m.health)}</div></div>
 <div class="grid stats gantt-stats">${[['活跃任务',m.active,`共 ${m.tasks} 项任务`],['按期率',m.onTimeRate+'%','未逾期占比'],['逾期任务',m.overdue,m.overdue?'需要跟进':'全部在计划内'],['7 天内到期',m.dueSoon,'本周需交付']].map((x,i)=>`<div class="card stat ${i===2&&m.overdue?'stat-alert':''}"><div class="label">${x[0]}</div><div class="num">${x[1]}</div><div class="muted">${x[2]}</div></div>`).join('')}</div>
 <div class="card gantt"><div class="gantt-scroll-hint">甘特图时间轴较长，请在下方横向滚动条中左右拖动查看完整排期。</div><div class="gantt-scroll"><div class="gantt-inner" style="--dayw:34px;--days:${days}">
 <div class="gantt-head"><div class="gantt-left gantt-corner"><b>项目 / 里程碑</b><span>${tl.lanes.length} 个项目 · ${days} 天</span></div><div class="gantt-right"><div class="gantt-months">${monthGroups.map(g=>`<div class="gmonth" style="--span:${g.count}">${g.year} 年 ${g.month+1} 月</div>`).join('')}</div><div class="gantt-days">${dayCells.map(c=>`<div class="gday ${c.weekend?'wknd':''} ${Date.parse(tl.range.start)+c.i*DAY===Date.parse(tl.range.today)?'is-today':''}">${c.label}</div>`).join('')}</div></div></div>
 ${tl.lanes.map(l=>`<div class="gantt-row"><div class="gantt-left"><div class="gl-title"><b>${esc(l.name)}</b>${pill(l.status)}</div><div class="muted">${esc(l.ownerName)} · 交付 ${esc(l.targetDate||'待定')} · 完成 ${l.pct}%</div><div class="bar" style="margin-top:8px"><i style="width:${l.pct}%"></i></div>${l.risks.length?`<div class="grisk">⚠ ${esc(l.risks[0])}${l.risks.length>1?` 等 ${l.risks.length} 项`:''}</div>`:`<div class="gok">✓ 进度正常</div>`}</div>
 <div class="gantt-right gtrack" style="height:${rowHeight(l)}px">${dayCells.map(c=>`<div class="gcol ${c.weekend?'wknd':''}" style="left:calc(var(--dayw) * ${c.i})"></div>`).join('')}
 ${l.milestones.map(ms=>`<div class="gmile" style="left:${ganttPct(Date.parse(ms.date),tl.range.startMs,tl.range.spanMs)}%" title="${esc(ms.label)} · ${esc(ms.date)}"><i></i><span>${esc(ms.label)}</span></div>`).join('')}
 ${l.bars.map((b,i)=>ganttBar(b,tl).replace('style="left:',`style="top:${BAR_PAD+i*(BAR_H+BAR_GAP)}px;left:`)).join('')}
 ${l.bars.length?'':'<div class="gempty">该项目暂无已排期任务</div>'}
 </div></div>`).join('')}
 <div class="gantt-row gantt-today-row"><div class="gantt-left"><b>今天</b><div class="muted">${esc(tl.range.today)}</div></div><div class="gantt-right">${todayIn?`<div class="gtoday" style="left:${todayPct}%"><span>今天</span></div>`:''}</div></div>
 </div></div><div class="gantt-legend">${tl.statuses.map(s=>`<span><i class="${STATUS_CLASS[s]||'st-todo'}"></i>${esc(s)}</span>`).join('')}<span><i class="is-late"></i>已逾期</span><span><i class="gmile-dot"></i>里程碑 / 交付节点</span></div></div>
 <div class="grid cols" style="margin-top:16px"><div class="card section-card"><div class="row" style="margin-bottom:6px"><div><b>资源负荷</b><div class="muted">按人在手工时排序，识别过度分配</div></div></div><ul class="list">${tl.load.map(x=>`<li><div style="flex:1"><b>${esc(x.name)}</b><div class="muted">${x.tasks} 项任务 · ${x.active} 项进行中</div></div><div style="text-align:right;min-width:92px"><b>${x.hours}h</b><div class="bar" style="margin-top:7px"><i style="width:${Math.min(100,x.hours/40*100)}%"></i></div></div></li>`).join('')||'<li><div class="muted">暂无任务分配</div></li>'}</ul></div>
 <div class="card section-card"><div class="row" style="margin-bottom:6px"><div><b>风险与待跟进</b><div class="muted">需要项目管理介入的事项</div></div>${tl.risks.length?pill('风险'):pill('正常')}</div><ul class="list">${tl.risks.map(r=>`<li><div class="muted" style="color:var(--ink)">⚠ ${esc(r)}</div></li>`).join('')||'<li><div class="muted">✓ 暂无逾期或未分配任务</div></li>'}</ul></div></div>`}
function settings(){if(state.me?.role!=='项目管理')return `<div class="card section-card"><div class="title">无权限</div><div class="muted">模型服务配置仅由项目管理维护。</div></div>`;return `<div class="row"><div><div class="title">模型服务配置</div><div class="muted">配置兼容 OpenAI 接口的 URL 和 Key，并获取模型列表。</div></div></div><div class="card section-card"><form id="settings-form"><div class="field"><label>API URL</label><input name="aiBaseUrl" value="${esc(state.db.settings?.aiBaseUrl||'')}" placeholder="https://api.openai.com/v1"></div><div class="field"><label>API Key</label><input name="aiApiKey" type="password" placeholder="输入后保存"></div><div class="field"><label>模型</label><select name="aiModel"><option value="${esc(state.db.settings?.aiModel||'')}">${esc(state.db.settings?.aiModel||'请先获取模型列表')}</option></select></div><div class="actions"><button class="btn" type="button" data-action="models">获取模型列表</button><button class="btn primary">保存配置</button></div></form></div>`}
function users(){if(state.me?.role!==ROLE_ADMIN)return `<div class="card section-card"><div class="title">无权限</div><div class="muted">账号与模型配置仅由项目管理维护。</div></div>`;return `<div class="row"><div><div class="eyebrow">ACCESS CONTROL</div><div class="title">账号管理</div><div class="muted">角色权限分为项目管理、产品、开发、测试四类，仅项目管理可新增或修改账号。</div></div><button class="btn primary" data-action="new-user">＋ 添加成员</button></div><div class="grid user-grid">${ROLES.map(r=>`<div class="card section-card"><h3>${esc(r[0])}</h3><div class="muted">${esc(r[1])}</div></div>`).join('')}</div><div class="card" style="margin-top:16px"><table><thead><tr><th>成员</th><th>账号</th><th>职位</th><th>角色</th><th>状态</th><th></th></tr></thead><tbody>${state.db.users.map(u=>`<tr><td><b>${esc(u.name)}</b></td><td class="muted">${esc(u.username||'—')}</td><td>${esc(u.title)}</td><td>${pill(u.role)}</td><td>${u.active?'<span class="pill status-已完成">启用</span>':'<span class="pill status-待开始">停用</span>'}</td><td style="text-align:right">${u.id===state.me?.id?'<span class="muted">当前登录</span>':`<button class="btn" data-action="toggle-user" data-user="${esc(u.id)}">${u.active?'停用':'启用'}</button>`}</td></tr>`).join('')}</tbody></table></div>`}
const KFLABEL={doc:'需求文档（RPD）',proto:'交互原型 Demo'};
function mdInline(s){return s.replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/(^|[^*])\*([^*\n]+)\*/g,'$1<em>$2</em>').replace(/\[([^\]]+)\]\((https?:[^)\s]+)\)/g,'<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>')}
function mdRender(src){const lines=esc(src).replace(/\r\n?/g,'\n').split('\n');const out=[];let i=0,list=null;
 const closeList=()=>{if(list){out.push(`</${list}>`);list=null}};
 const isRow=s=>/^\s*\|.*\|\s*$/.test(s);
 const cells=s=>s.trim().replace(/^\||\|$/g,'').split('|').map(c=>c.trim());
 while(i<lines.length){const line=lines[i],t=line.trim();
  if(/^```/.test(t)){closeList();const buf=[];i++;while(i<lines.length&&!/^```/.test(lines[i].trim()))buf.push(lines[i++]);i++;out.push(`<pre><code>${buf.join('\n')}</code></pre>`);continue}
  if(!t){closeList();i++;continue}
  const h=t.match(/^(#{1,4})\s+(.*)$/);
  if(h){closeList();out.push(`<h${Math.min(h[1].length+1,5)}>${mdInline(h[2])}</h${Math.min(h[1].length+1,5)}>`);i++;continue}
  if(/^(---|\*\*\*|___)$/.test(t)){closeList();out.push('<hr>');i++;continue}
  if(isRow(t)&&i+1<lines.length&&/^\s*\|[\s:|-]+\|\s*$/.test(lines[i+1])){closeList();const head=cells(t);i+=2;const body=[];while(i<lines.length&&isRow(lines[i]))body.push(cells(lines[i++]));out.push(`<div class="md-table-wrap"><table class="md-table"><thead><tr>${head.map(c=>`<th>${mdInline(c)}</th>`).join('')}</tr></thead><tbody>${body.map(r=>`<tr>${r.map(c=>`<td>${mdInline(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`);continue}
  const ul=line.match(/^\s*[-*+]\s+(.*)$/),ol=line.match(/^\s*\d+[.)]\s+(.*)$/);
  if(ul||ol){const want=ul?'ul':'ol';if(list!==want){closeList();out.push(`<${want}>`);list=want}out.push(`<li>${mdInline((ul||ol)[1])}</li>`);i++;continue}
  if(/^>\s?/.test(t)){closeList();out.push(`<blockquote>${mdInline(t.replace(/^>\s?/,''))}</blockquote>`);i++;continue}
  closeList();out.push(`<p>${mdInline(t)}</p>`);i++}
 closeList();return out.join('')}
async function openRequirement(id){state.view='requirement';state.selectedRequirementId=id;state.files=null;state.history=[];state.splitDraft=[];render();
 // 附件与操作历史并行拉取，谁先回来都不影响首屏
 try{[state.files,state.history]=await Promise.all([api(`/api/requirements/${id}/files`),api(`/api/requirements/${id}/history`).then(x=>x.history||[]).catch(()=>[])])}catch(e){toast(e.message)}render()}
async function uploadFile(id,kind,file){if(!file)return;try{const r=await fetch(`/api/requirements/${id}/files/${kind}/${encodeURIComponent(file.name)}`,{method:'PUT',headers:{'content-type':file.type||'application/octet-stream'},body:file});const d=await r.json().catch(()=>({}));if(!r.ok)return toast(d.error||`上传失败（${r.status}）`);state.files={id,...d};const hit=(d[kind]||[]).find(f=>f.name===file.name);toast(d.unchanged?'内容与当前版本一致，未产生新版本':`已保存 ${file.name}（v${hit?hit.version:'新'}）`);render()}catch(e){toast('上传失败：'+e.message)}}
async function removeFile(id,kind,name){if(!confirm(`确定移除「${name}」？历史版本仍保留在 git 中，此处不再展示。`))return;try{const r=await api(`/api/requirements/${id}/files/${kind}/${encodeURIComponent(name)}`,{method:'DELETE'});state.files={id,...r};toast('已移除');render()}catch(e){toast(e.message)}}
async function previewFile(id,kind,name,version){const src=`/api/requirements/${id}/files/${kind}/${encodeURIComponent(name)}${version?`?version=${version}`:''}`;$('#preview')?.remove();
 $('#app').insertAdjacentHTML('beforeend',`<div class="modal open preview-modal" id="preview"><div class="dialog dialog-wide preview-dialog"><div class="dialog-head"><div><div class="eyebrow">${kind==='proto'?'原型预览 · 沙箱运行 · 演示数据':'文档预览'}</div><h2>${esc(name)}${version?` · v${version}`:''}</h2></div><div class="preview-actions"><a class="btn" href="${src}" target="_blank" rel="noopener">新窗口打开</a><button type="button" class="icon-btn" data-action="close-preview" aria-label="关闭">×</button></div></div><div class="preview-body" id="preview-body"><div class="muted" style="padding:24px">正在加载…</div></div></div></div>`);
 const modal=$('#preview'),body=$('#preview-body');const close=()=>{modal?.classList.add('closing');setTimeout(()=>modal?.remove(),160)};
 modal.querySelectorAll('[data-action="close-preview"]').forEach(b=>b.onclick=close);
 modal.addEventListener('click',e=>{if(e.target===modal)close()});
 document.addEventListener('keydown',function onEsc(e){if(e.key==='Escape'){close();document.removeEventListener('keydown',onEsc)}});
 try{const html=await (await fetch(src,{cache:'no-store'})).text();if(kind==='proto'){const srcdoc=html.replace(/&/g,'&amp;').replace(/"/g,'&quot;');body.innerHTML=`<iframe class="proto-frame" sandbox="allow-scripts" srcdoc="${srcdoc}" title="${esc(name)}"></iframe>`}else{body.innerHTML=`<div class="doc-view md-doc">${mdRender(html)}</div>`}}catch(e){body.innerHTML=`<div class="muted" style="padding:24px">${esc(e.message)}</div>`}}
function fileRow(id,kind,f){const chain=f.versions.map(x=>`<button class="ver-chip ${x.version===f.version?'current':''}" data-preview="${esc(f.name)}" data-kind="${kind}" data-ver="${x.version}" title="${esc(x.subject)} · ${esc(x.author)}">v${x.version}</button>`).join('');
 return `<div class="file-item"><div class="file-main"><div class="file-name"><span class="file-ico">${kind==='proto'?'▷':'≡'}</span><b>${esc(f.name)}</b><span class="ver-badge">v${f.version}</span></div><div class="muted">${(f.size/1024).toFixed(1)} KB · ${esc(f.updatedBy)} · ${esc(String(f.updatedAt).slice(0,10))}</div><div class="ver-chain"><span class="muted">版本</span>${chain}</div></div><div class="file-ops"><button class="btn" data-preview="${esc(f.name)}" data-kind="${kind}" data-ver="${f.version}">预览</button><a class="btn" href="/api/requirements/${id}/files/${kind}/${encodeURIComponent(f.name)}" target="_blank" rel="noopener">新窗口</a><button class="btn" data-remove="${esc(f.name)}" data-kind="${kind}">移除</button></div></div>`}
function filesPanel(id,kind,files){const accept=kind==='proto'?'.html':'.md,.markdown,.txt';
 return `<div class="card section-card file-panel"><div class="row file-panel-head"><div><b>${KFLABEL[kind]}</b><div class="muted">${kind==='proto'?'上传单文件 HTML 原型，在沙箱中运行：不接后端、数据为演示数据、无法读取研发台登录态。':'上传 Markdown 格式的 RPD，更新后自动生成新版本，可回看任一历史版本。'}</div></div><label class="btn primary">上传<input type="file" class="file-input" data-kind="${kind}" accept="${accept}" style="display:none"></label></div>
 ${files.length?`<div class="file-list">${files.map(f=>fileRow(id,kind,f)).join('')}</div>`:`<div class="empty-state" style="min-height:120px"><div class="empty-icon">⌁</div><span>还没有${KFLABEL[kind]}。</span></div>`}</div>`}
// ── 需求详情工作台：状态流转 / 指派 / 排期 / 拆分 / 操作历史 ──
// 所有按钮的可用性都来自 lifecycle.js 的 availableActions，与服务端校验同源，不会出现「点得动但被拒」
const role=()=>state.me?.role||'';
function reqCtx(r,taskCount){const p=project(r.projectId);return {role:role(),taskCount:taskCount??state.db.tasks.filter(t=>t.requirementId===r.id).length,projectTarget:p?.targetDate||''}}
function reqActions(r,taskCount){return availableActions(r,reqCtx(r,taskCount))}
function ownerOptions(selected,roles){return `<option value="">待分配</option>`+state.db.users.filter(u=>!roles||roles.includes(u.role)).map(u=>`<option value="${esc(u.id)}" ${u.id===selected?'selected':''}>${esc(u.name)}（${esc(u.role)}）</option>`).join('')}
function teamName(id){return user(id)?.name||'待分配'}
const FLOW_HINT={未确定:'收集箱：先补描述',待评审:'产品与研发一起过',已确定:'等排期',已排期:'等开工',开发中:'写代码',测试中:'提测验收',已完成:'交付完成'};
function flowPanel(r,avail){const cur=r.status;
 const step=(s,i)=>{const cls=s===cur?'flow-on':'',hit=FLOW.indexOf(s)<FLOW.indexOf(cur);
  let title=STATUS_META[s]?.hint||'';const act=avail.actions.find(a=>a.to===s);
  if(s===TERMINATED)title='已终止：保留记录，可重启';
  else if(hit)title='已完成该阶段';
  else if(!avail.actions.length)title='当前状态没有可执行动作';
  if(act)title=(act.allowed?`可执行：`:`需要 ${act.roles.map(x=>x.label).join(' / ')}：`)+act.roles.map(x=>x.reason).filter(Boolean)[0];
  return `<div class="flow-step ${cls} ${hit?'flow-done':''} ${act&&!act.allowed?'flow-locked':''}" title="${esc(title)}"><i>${i+1}</i><b>${esc(STATUS_META[s]?.short||s)}</b><span>${esc(FLOW_HINT[s]||'')}</span></div>`};
 const buttons=avail.actions.map(a=>{const why=a.roles.map(x=>x.reason).filter(Boolean)[0]||'';
  return `<button class="btn ${a.allowed?'primary':''}" data-transition="${esc(a.to)}" ${a.allowed?'':'disabled'} title="${a.allowed?esc(why):`需要 ${a.roles.map(x=>x.label).join(' / ')}：${esc(why)}`}">${a.allowed?'→ ':''}${esc(a.to)}</button>`}).join('');
 const terminated=r.status===TERMINATED;
 return `<div class="card section-card"><div class="row" style="margin-bottom:12px"><div><b>状态流转</b><div class="muted">${esc(STATUS_META[cur]?.hint||'')}</div></div>${terminated?pill(TERMINATED):''}</div>
 <div class="flow-map">${FLOW.map(step).join('')}${terminated?`<div class="flow-step flow-off"><i>×</i><b>已终止</b><span>已移出主流程</span></div>`:''}</div>
 <div class="flow-ops"><div class="flow-action-row">${buttons||'<span class="muted">当前角色没有可执行的流转动作</span>'}${avail.canTerminate?`<button class="btn danger" data-terminate="1">终止需求</button>`:''}</div>
 <div class="field" style="margin-top:12px"><label>流转说明（可选，会记入历史；终止必填）</label><input id="transition-reason" placeholder="例如：验收标准已与客户确认 / 客户临时撤单"></div></div></div>`}
function assignPanel(r){const devs=state.db.users.filter(u=>['开发','测试'].includes(u.role));
 const collab=(r.collaboratorIds||[]).map(id=>`<label class="chip"><input type="checkbox" data-collab value="${esc(id)}" ${(r.collaboratorIds||[]).includes(id)?'checked':''}>${esc(teamName(id))}</label>`).join('');
 const picked=(r.collaboratorIds||[]).map(id=>teamName(id)).join('、')||'暂无';
 return `<div class="card section-card"><div class="row" style="margin-bottom:10px"><div><b>指派</b><div class="muted">主责开发对需求交付负责，协作成员一起拆任务</div></div>${r.assigneeId?pill('已指派'):pill('待指派')}</div>
 <div class="formgrid"><div class="field"><label>主责开发</label><select id="assignee-select">${ownerOptions(r.assigneeId,['开发','测试'])}</select></div><div class="field"><label>参与角色</label><input value="${esc(picked)}" readonly class="readonly-input"></div></div>
 <div class="field"><label>协作成员（可多选）</label><div class="chips">${devs.map(u=>`<label class="chip"><input type="checkbox" data-collab value="${esc(u.id)}" ${(r.collaboratorIds||[]).includes(u.id)?'checked':''}>${esc(u.name)}</label>`).join('')||'<span class="muted">暂无开发/测试角色成员</span>'}</div></div>
 <div class="actions" style="justify-content:flex-start;margin-top:10px"><button class="btn primary" data-action="save-assign">保存指派</button></div></div>`}
function schedulePanel(r){const p=project(r.projectId),over=!!(p?.targetDate&&r.planEnd&&r.planEnd>p.targetDate);
 // 相对基线的偏差：正数=推迟，负数=提前。改期不隐藏历史，只把差距摆在明面上
 const drift=(now,base)=>{if(!now)return '—';if(!base)return now;const days=Math.round((Date.parse(now)-Date.parse(base))/864e5);return days?`${now}（较基线${days>0?'推迟':'提前'} ${Math.abs(days)} 天）`:`${now}（与基线一致）`};
 return `<div class="card section-card"><div class="row" style="margin-bottom:10px"><div><b>计划与改期</b><div class="muted">项目目标交付 ${esc(p?.targetDate||'未设置')}；改期会自动保留基线</div></div><span class="result-count">改期 ${r.rescheduleCount||0} 次</span></div>
 <div class="formgrid"><div class="field"><label>计划开始</label><input id="plan-start" type="date" value="${esc(r.planStart||'')}"></div><div class="field"><label>计划结束</label><input id="plan-end" type="date" value="${esc(r.planEnd||'')}"></div></div>
 ${over?`<div class="cell-hint warn">⚠ 计划结束 ${esc(r.planEnd)} 晚于项目目标 ${esc(p.targetDate)}，需项目管理确认后重试</div>`:''}
 ${r.baseline?`<div class="baseline"><b>基线（首次排期）</b><div class="muted">开始 ${esc(r.baseline.planStart||'—')} · 结束 ${esc(r.baseline.planEnd||'—')} · 记录于 ${esc(r.baseline.capturedAt||'—')}</div><div class="muted">当前开始 ${esc(drift(r.planStart,r.baseline.planStart))}</div><div class="muted">当前结束 ${esc(drift(r.planEnd,r.baseline.planEnd))}</div></div>`:'<div class="muted" style="margin-top:10px">尚未产生基线，首次排期后系统自动留存。</div>'}
 <div class="actions" style="justify-content:flex-start;margin-top:10px"><button class="btn primary" data-action="save-schedule">保存排期</button></div></div>`}
function taskRowHtml(t,r){const g=taskGranularity(t.estimateHours);
 return `<div class="split-row" data-task-row="${esc(t.id)}"><div class="split-title"><b>${esc(t.title)}</b><div class="muted">${esc(t.estimateHours)}h · ${esc((t.estimateHours/SPLIT.MIN_PER_DEV_DAY).toFixed(1))} 人日</div>${g.level!=='ok'?`<div class="cell-hint ${g.level==='warn'?'warn':'err'}">${esc(g.message)}</div>`:''}</div><select data-task-owner="${esc(t.id)}">${ownerOptions(t.ownerId,['开发','测试'])}</select><select data-task-status="${esc(t.id)}">${['待开始','开发中','测试中','已完成'].map(s=>`<option ${s===t.status?'selected':''}>${s}</option>`).join('')}</select><input type="date" data-task-start="${esc(t.id)}" value="${esc(t.startDate||'')}"><input type="date" data-task-due="${esc(t.id)}" value="${esc(t.dueDate||'')}"><button class="icon-btn" title="删除任务" data-del-task="${esc(t.id)}">×</button></div>`}
function draftRowHtml(t,i){const g=taskGranularity(t.estimateHours);
 return `<div class="split-row draft"><div class="split-title"><input data-draft-field="title" data-i="${i}" value="${esc(t.title)}" placeholder="任务名称，例：渠道录入页面与校验"></div><input type="number" min="1" max="80" step="1" data-draft-field="estimateHours" data-i="${i}" value="${esc(t.estimateHours)}" title="预估工时（小时）"><select data-draft-field="assigneeId" data-i="${i}">${ownerOptions(t.assigneeId,['开发','测试'])}</select><input type="date" data-draft-field="startDate" data-i="${i}" value="${esc(t.startDate||'')}"><input type="date" data-draft-field="dueDate" data-i="${i}" value="${esc(t.dueDate||'')}"><button class="icon-btn" title="移除这一行" data-del-draft="${i}">×</button>${g.level!=='ok'?`<div class="cell-hint ${g.level==='warn'?'warn':'err'}">${esc(g.message)}</div>`:''}</div>`}
function splitPanel(r,ts){const bal=splitBalance(r.estimatePoints,ts);
 return `<div class="card section-card"><div class="row" style="margin-bottom:10px"><div><b>拆分任务</b><div class="muted">需求要落到 4–24 小时（0.5–3 人日）的颗粒度，才能被排期、被跟踪、被验收</div></div><span class="result-count">${ts.length} 项 · ${ts.reduce((s,t)=>s+(Number(t.estimateHours)||0),0)}h</span></div>
 ${ts.length?`<div class="split-list">${ts.map(t=>taskRowHtml(t,r)).join('')}</div>`:`<div class="empty-state" style="min-height:100px"><span>这条需求还没有拆分任务。添加第一行开始拆分 →</span></div>`}
 <div class="split-sum ${bal.level}">${esc(bal.message)}${bal.expect?`（需求规模 ${r.estimatePoints} pts ≈ ${bal.expect}h）`:''}</div>
 <div class="split-draft-head"><b>新增拆分</b><span class="muted">填好后一次提交，中途不落库</span></div>
 <div class="split-list">${state.splitDraft.map((t,i)=>draftRowHtml(t,i)).join('')||'<div class="muted" style="padding:10px 2px">还没有待提交的任务行。</div>'}</div>
 <div class="actions" style="justify-content:flex-start;margin-top:10px"><button class="btn" data-action="add-draft-row">＋ 添加一行</button><button class="btn primary" data-action="save-split" ${state.splitDraft.length?'':'disabled'}>提交拆分（${state.splitDraft.length}）</button></div></div>`}
function historyPanel(r){const rows=state.history.filter(h=>h.requirementId===r.id);
 return `<div class="card section-card"><div class="row" style="margin-bottom:8px"><div><b>操作历史</b><div class="muted">谁在什么时候把需求推到了哪一步</div></div><span class="result-count">${rows.length} 条</span></div>
 ${rows.length?`<ul class="hist">${rows.map(h=>`<li><span class="hist-dot ${h.to===TERMINATED?'danger':''}"></span><div class="hist-body"><b>${esc(h.actorName)}</b><span class="pill status">${esc(h.actorRole||'—')}</span><span class="hist-act">${esc(h.action)}</span>${h.from||h.to?`<span class="muted">${esc(h.from||'')}${h.from&&h.to?' → ':''}${esc(h.to||'')}</span>`:''}<div class="muted">${esc(h.detail||'')}</div></div><time class="muted">${esc(h.date||'')}</time></li>`).join('')}</ul>`:'<div class="muted">暂无操作记录。流转、指派、改期、拆分都会记在这里。</div>'}</div>`}
function requirementDetail(){const r=state.db.requirements.find(x=>x.id===state.selectedRequirementId);
 if(!r)return `<div class="card section-card"><div class="title">需求不存在</div><div class="actions" style="justify-content:flex-start"><button class="btn" data-action="back-to-requirements">返回需求池</button></div></div>`;
 const f=state.files&&state.files.id===r.id?state.files:null;
 const ts=state.db.tasks.filter(t=>t.requirementId===r.id);
 const avail=reqActions(r,ts.length);
 const collab=(r.collaboratorIds||[]).map(id=>user(id)?.name).filter(Boolean);
 return `<div class="row detail-head"><div><button class="btn" data-action="back-to-requirements">← 返回需求池</button><div class="eyebrow" style="margin-top:14px">REQUIREMENT DETAIL · ${esc(r.id)}</div><div class="title">${esc(r.title)}</div><div class="detail-meta">${pill(r.priority,'priority')} ${pill(r.status)}<span class="muted">${esc(project(r.projectId)?.name||'未归属项目')} · 记录人 ${esc(user(r.ownerId)?.name||'待分配')} · 主责开发 ${esc(teamName(r.assigneeId))}${collab.length?' · 协作 '+esc(collab.join('、')):''} · ${esc(r.estimatePoints||0)} pts · 创建于 ${esc(r.createdAt||'—')}</span></div></div><div class="detail-progress"><div class="muted">拆分任务完成度</div><b>${esc(r.progress||deriveProgress(ts))}</b></div></div>
 <div class="grid detail-grid"><div class="detail-main">
  <div class="card section-card"><b>需求背景与描述</b><div class="doc-view req-desc">${r.description?mdRender(r.description):'<div class="muted">暂无描述。</div>'}</div>${r.acceptance?`<div class="acceptance"><b>验收标准</b><div>${esc(r.acceptance)}</div></div>`:''}${r.source?`<div class="muted" style="margin-top:12px">来源：${esc(r.source)}</div>`:''}</div>
  ${flowPanel(r,avail)}
  ${assignPanel(r)}
  ${schedulePanel(r)}
  ${splitPanel(r,ts)}
  ${historyPanel(r)}
 </div><div class="detail-side">${f?filesPanel(r.id,'doc',f.doc):`<div class="card section-card"><div class="muted">正在加载附件…</div></div>`}${f?filesPanel(r.id,'proto',f.proto):''}</div></div>`}
// ── 工作台动作：每个动作都先刷新服务端数据再重绘，界面永远等于库里的事实 ──
const currentReq=()=>state.db.requirements.find(x=>x.id===state.selectedRequirementId);
const reasonText=()=>($('#transition-reason')?.value||'').trim();
async function refreshHist(id){try{state.history=(await api(`/api/requirements/${id}/history`)).history||[]}catch(e){state.history=[]}}
async function afterWrite(keepDraft){if(!keepDraft)state.splitDraft=[];state.db=await api('/api/bootstrap');await refreshHist(state.selectedRequirementId);render()}
async function doTransition(to){const r=currentReq();if(!r)return;let reason=reasonText();
 if(to===TERMINATED){if(!reason)return toast('终止需求必须填写原因');if(!confirm(`确认终止「${r.title}」？终止后仍可在历史中回看，并支持重启。`))return}
 try{const res=await api(`/api/requirements/${r.id}/transition`,{method:'POST',body:JSON.stringify({to,reason})});toast(`已流转到「${res.requirement.status}」`);await afterWrite(true)}catch(e){toast(e.message+(e.gates?.length>1?`（共 ${e.gates.length} 项未满足：${e.gates.slice(1).join('；')}）`:''))}}
async function saveAssign(){const r=currentReq();if(!r)return;const assigneeId=$('#assignee-select')?.value||'',collaboratorIds=[...document.querySelectorAll('[data-collab]:checked')].map(x=>x.value);
 try{await api(`/api/requirements/${r.id}`,{method:'PATCH',body:JSON.stringify({assigneeId,collaboratorIds})});toast('指派已保存');await afterWrite(true)}catch(e){toast(e.message)}}
async function saveSchedule(force=false){const r=currentReq();if(!r)return;const planStart=$('#plan-start')?.value||'',planEnd=$('#plan-end')?.value||'';
 if(planStart&&planEnd&&planStart>planEnd)return toast('计划开始不能晚于计划结束');
 try{await api(`/api/requirements/${r.id}`,{method:'PATCH',body:JSON.stringify({planStart,planEnd,force})});toast('排期已保存');await afterWrite(true)}
 catch(e){if(e.status===409&&/晚于项目目标/.test(e.message)&&confirm(`${e.message}\n\n仍要按这个日期保存吗？`))return saveSchedule(true);toast(e.message)}}
async function saveSplit(){const r=currentReq();if(!r)return;if(!state.splitDraft.length)return toast('请先添加待提交的任务行');
 try{const res=await api(`/api/requirements/${r.id}/tasks`,{method:'POST',body:JSON.stringify({tasks:state.splitDraft})});
  toast(`已拆分 ${res.tasks.length} 条任务`+(res.warnings?.length?`，其中 ${res.warnings.length} 条有颗粒度提示`:''));await afterWrite(false)}
 catch(e){const extra=e.details?.length?`\n${e.details.join('\n')}`:'';toast('拆分失败：'+e.message+extra)}}
async function patchTask(id,patch){try{await api(`/api/tasks/${id}`,{method:'PATCH',body:JSON.stringify(patch)});state.db=await api('/api/bootstrap');if(patch.status)toast('任务状态已更新，需求进度同步刷新');render()}catch(e){toast(e.message)}}
async function deleteTask(id){if(!confirm('确定删除这个拆分任务？该操作会记入需求历史。'))return;try{await api(`/api/tasks/${id}`,{method:'DELETE'});state.db=await api('/api/bootstrap');await refreshHist(state.selectedRequirementId);toast('已删除');render()}catch(e){toast(e.message)}}
