 $('#app').insertAdjacentHTML('beforeend',`<div class="modal open" id="modal"><div class="dialog"><div class="dialog-head"><div><div class="eyebrow">${head[0]}</div><h2>${head[1]}</h2></div><button type="button" class="icon-btn" aria-label="关闭" data-action="close-modal">×</button></div><form id="modal-form">${isUser?'':nameField}${modalFields(type)}<div class="actions"><button type="button" class="btn" data-action="close-modal">取消</button><button class="btn primary">保存</button></div></form></div></div>`);
