// 暴露给离线自测夹具（scripts/selftest.mjs）的内部句柄。浏览器里没人 import 这个模块，所以多这一个 export 不产生任何副作用。
export const __test=()=>({state,view,render,reqActions,reqCtx,role,splitBalance,taskGranularity,doTransition,saveAssign,saveSchedule,saveSplit,patchTask,deleteTask});
(async()=>{try{const m=await api('/api/auth/me');state.me=m.user;state.db=await api('/api/bootstrap');render()}catch(e){if(e.status!==401){console.error(e);document.querySelector('#app').innerHTML=`<div class="login-wrap"><div class="card section-card"><h2>工作台加载失败</h2><p role="alert">${esc(e.message)}</p><button class="btn primary" id="retry-load">重新加载</button></div></div>`;$('#retry-load').onclick=()=>location.reload();return}document.querySelector('#app').innerHTML=`<div class="login-wrap"><div class="login-card"><div class="login-brand"><div class="login-mark">星</div><h2>把想法，<br>变成交付。</h2><p>轻量化的需求管理与研发协作空间。让产品、研发与项目管理围绕同一张交付地图工作。</p><div class="muted" style="color:#9eacc4;margin-top:50px">AI PRODUCT STUDIO · MVP</div></div><div class="login-form"><h3>欢迎回来</h3><p>登录星河研发台，继续管理你的项目。</p><form id="login-form"><div class="field"><label for="login-username">账号</label><input id="login-username" name="username" autocomplete="username" value="manager" required></div><div class="field password-field"><label for="login-password">密码</label><div class="password-input-wrap"><input id="login-password" name="password" type="password" value="demo123" required autocomplete="current-password"><button type="button" class="password-toggle" data-action="toggle-password" aria-label="显示密码" title="显示密码">◉</button></div></div><button type="submit" class="btn primary">进入工作台</button><p id="login-error" role="alert" style="color:#c94f59" hidden></p><div class="muted" style="margin-top:18px">演示账号：manager / demo123<br>产品：product / demo123 · 开发：chen / demo123 · 测试：shen / demo123</div></form></div></div></div>`;$('#login-form').onsubmit=async ev=>{ev.preventDefault();const btn=ev.target.querySelector('button[type=submit],button:not([type])');if(btn){btn.disabled=true;btn.textContent='登录中…'}$('#login-error').hidden=true;try{const payload=Object.fromEntries(new FormData(ev.target));payload.username=String(payload.username||'').trim();payload.password=String(payload.password||'');await api('/api/auth/login',{method:'POST',body:JSON.stringify(payload)});const m=await api('/api/auth/me');state.me=m.user;state.db=await api('/api/bootstrap');render()}catch(err){const el=$('#login-error');if(el){el.textContent=err.message==='Failed to fetch'?'无法连接服务器，请稍后重试':err.message;el.hidden=false}if(btn){btn.disabled=false;btn.textContent='进入工作台'}}};$('.password-toggle').onclick=ev=>{const input=$('#login-password');const visible=input.type==='text';input.type=visible?'password':'text';ev.currentTarget.textContent=visible?'◉':'◎';ev.currentTarget.setAttribute('aria-label',visible?'显示密码':'隐藏密码');ev.currentTarget.title=visible?'显示密码':'隐藏密码'}}})();
